"use client";

import { useState } from "react";
import { ChevronLeft, ChevronRight, Plus, X, Save, Calendar as CalIcon, FileText } from "lucide-react";
import { format, addMonths, subMonths, startOfMonth, endOfMonth, startOfWeek, endOfWeek, isSameMonth, isSameDay, addDays } from "date-fns";
import { nl } from "date-fns/locale"; // Tarihleri Hollandaca formatlamak için
import { createNewTask } from "@/app/actions/task-actions";

export default function CalendarClient({ initialTasks }: { initialTasks: any[] }) {
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [loading, setLoading] = useState(false);
  
  // Form States
  const [title, setTitle] = useState("");
  const [type, setType] = useState("agenda");

  // Veritabanından gelen verileri tarihlere göre haritalama
  const taskMap = initialTasks.reduce((acc: any, task) => {
    try {
      const data = JSON.parse(task.description || "{}");
      const dateKey = data.datum;
      if (!acc[dateKey]) acc[dateKey] = [];
      acc[dateKey].push({ ...task, data });
    } catch (e) { console.error("Parse error"); }
    return acc;
  }, {});

  const handleSave = async () => {
    if (!title || !selectedDate) return;
    setLoading(true);
    const data = {
      titel: title,
      sprint: "0",
      documentType: type,
      datum: format(selectedDate, "yyyy-MM-dd"),
    };
    const res = await createNewTask(data);
    if (res.success) {
      setTitle("");
      setSelectedDate(null);
      // Not: Sayfayı yenilemek için router.refresh() eklenebilir
      window.location.reload(); 
    }
    setLoading(false);
  };

  return (
    <div className="max-w-[1600px] mx-auto relative px-4 py-8">
      
      {/* HEADER - HOLLANDACA */}
      <div className="flex justify-between items-center mb-10 border-b border-white/5 pb-8">
        <div>
          <h1 className="text-5xl font-black text-white italic tracking-tighter uppercase leading-none">Temporal Grid</h1>
          <p className="text-fuchsia-500 text-[10px] font-bold tracking-[0.6em] uppercase mt-2">Status: Operationeel</p>
        </div>
        <div className="flex items-center gap-6 bg-[#0a0e17] border border-white/10 p-2 rounded-xl shadow-xl">
          <button onClick={() => setCurrentMonth(subMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer hover:bg-white/5 rounded-lg"><ChevronLeft size={24} /></button>
          <span className="text-lg font-black text-white w-48 text-center uppercase tracking-widest italic">{format(currentMonth, "MMMM yyyy", { locale: nl })}</span>
          <button onClick={() => setCurrentMonth(addMonths(currentMonth, 1))} className="p-3 hover:text-fuchsia-500 text-teal-500 transition-all cursor-pointer hover:bg-white/5 rounded-lg"><ChevronRight size={24} /></button>
        </div>
      </div>

      {/* FULL WIDTH CALENDAR GRID */}
      <div className="bg-[#0a0e17]/80 border border-white/10 rounded-3xl overflow-hidden shadow-[0_0_50px_rgba(0,0,0,0.3)] backdrop-blur-xl">
        <div className="grid grid-cols-7 bg-white/5 py-5 border-b border-white/5 text-center">
          {["Ma", "Di", "Wo", "Do", "Vr", "Za", "Zo"].map(d => (
            <span key={d} className="text-[11px] font-black text-teal-500/40 uppercase tracking-[0.4em]">{d}</span>
          ))}
        </div>

        <div className="grid grid-cols-7">
          {(() => {
            const days = [];
            let day = startOfWeek(startOfMonth(currentMonth), { weekStartsOn: 1 });
            const endDate = endOfWeek(endOfMonth(currentMonth), { weekStartsOn: 1 });

            while (day <= endDate) {
              const formattedDate = format(day, "yyyy-MM-dd");
              const dayTasks = taskMap[formattedDate] || [];
              const isCurrentMonth = isSameMonth(day, currentMonth);
              const isToday = isSameDay(day, new Date());
              const currentDay = day;

              days.push(
                <div 
                  key={day.toString()} 
                  onClick={() => setSelectedDate(currentDay)}
                  className={`min-h-[150px] border border-white/5 p-4 transition-all cursor-pointer hover:bg-fuchsia-500/5 relative group ${!isCurrentMonth ? "opacity-10 pointer-events-none" : "opacity-100"}`}
                >
                  <span className={`text-xs font-mono mb-2 block ${isToday ? "text-fuchsia-500 font-black scale-125" : "text-teal-500/30"}`}>
                    {format(day, "d")}
                  </span>

                  <div className="space-y-1.5">
                    {dayTasks.map((t: any) => (
                      <div key={t.id} className={`text-[10px] px-2 py-1.5 truncate rounded-md border font-bold uppercase tracking-tighter ${
                        t.data.documentType === 'agenda' || t.data.documentType === 'assignment' 
                        ? 'bg-blue-600/10 border-blue-500/30 text-blue-400' 
                        : 'bg-fuchsia-600/10 border-fuchsia-500/30 text-fuchsia-400'
                      }`}>
                        {t.title}
                      </div>
                    ))}
                  </div>
                  
                  <div className="absolute bottom-3 right-3 opacity-0 group-hover:opacity-100 transition-all transform translate-y-1 group-hover:translate-y-0">
                    <Plus size={18} className="text-fuchsia-500" />
                  </div>
                </div>
              );
              day = addDays(day, 1);
            }
            return days;
          })()}
        </div>
      </div>

      {/* HOLLANDACA QUICK ADD OVERLAY */}
      {selectedDate && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#02040a]/90 backdrop-blur-md animate-in fade-in duration-300">
          <div className="bg-[#0E153A] border border-fuchsia-500/40 p-10 rounded-3xl w-full max-w-md shadow-[0_0_80px_rgba(217,70,239,0.2)] relative overflow-hidden">
            
            <button onClick={() => setSelectedDate(null)} className="absolute top-6 right-6 text-white/30 hover:text-white cursor-pointer"><X size={28} /></button>
            
            <div className="mb-10">
              <h3 className="text-fuchsia-500 font-black uppercase text-[10px] tracking-[0.5em] mb-3">Item Toevoegen Voor</h3>
              <p className="text-3xl font-black text-white italic tracking-tighter uppercase leading-none">
                {format(selectedDate, "dd MMMM yyyy", { locale: nl })}
              </p>
            </div>

            <div className="space-y-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black uppercase text-teal-500/50 block tracking-widest ml-1">Titel / Omschrijving</label>
                <input 
                  autoFocus
                  value={title} onChange={(e) => setTitle(e.target.value)}
                  className="w-full bg-[#070B24] border border-white/10 p-5 text-white font-bold focus:border-fuchsia-500 outline-none transition-all rounded-xl placeholder:text-white/10 shadow-inner"
                  placeholder="Bijv. Project Deadline..."
                />
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase text-teal-500/50 block tracking-widest ml-1">Categorie</label>
                <div className="grid grid-cols-2 gap-3">
                  {[
                    { id: 'agenda', label: '📅 Agenda' },
                    { id: 'assignment', label: '📝 Opdracht' },
                    { id: 'meeting', label: '🤝 Vergadering' },
                    { id: 'daily', label: '⚙️ Daily Scrum' }
                  ].map((cat) => (
                    <button 
                      key={cat.id}
                      onClick={() => setType(cat.id)}
                      className={`py-4 text-[10px] font-black uppercase border transition-all rounded-xl ${
                        type === cat.id 
                          ? 'bg-fuchsia-600 border-fuchsia-600 text-white shadow-[0_0_20px_rgba(217,70,239,0.6)] scale-105 z-10' 
                          : 'bg-[#070B24] border-white/5 text-white/40 hover:border-white/20'
                      }`}
                    >
                      {cat.label}
                    </button>
                  ))}
                </div>
              </div>

              <button 
                onClick={handleSave}
                disabled={loading || !title}
                className="w-full bg-white text-[#0E153A] font-black py-6 mt-4 hover:bg-fuchsia-500 hover:text-white transition-all uppercase text-xs tracking-[0.4em] rounded-2xl shadow-2xl active:scale-95 disabled:opacity-20"
              >
                {loading ? "Verwerken..." : "Bevestigen"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}