"use server";
import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

// CALENDER SAYFASI İÇİN: Direkt Calender tablosuna yazar
export async function createCalendarItem(data: any) {
  try {
    // NOT: Şemanda userId zorunlu olduğu için burada geçerli bir ID olmalı.
    // Session'dan kullanıcı ID'sini alamıyorsan geçici olarak manuel bir ID koyabilirsin.
    const newItem = await prisma.calender.create({
      data: {
        userId: data.userId || "buraya-kendi-user-idni-koy", 
        title: data.titel,
        description: data.documentType, // 'agenda', 'assignment' vb.
        startDatetime: new Date(data.datum), // String'i DateTime'a çevirir
        endDatetime: new Date(data.datum),
      },
    });

    revalidatePath("/calendar");
    return { success: true, data: newItem };
  } catch (error: any) {
    console.error("Prisma Calender Error:", error);
    return { success: false, error: error.message };
  }
}

// TAKEN SAYFASI İÇİN: Mevcut Task tablosuna yazan fonksiyonun (Dokümanlar için)
export async function createNewTask(data: any) {
  try {
    const newTask = await prisma.task.create({
      data: {
        userId: "buraya-kendi-user-idni-koy",
        title: data.titel,
        description: JSON.stringify({
          documentType: data.documentType,
          sprint: data.sprint,
          datum: data.datum,
        }),
        status: "TODO",
      },
    });
    revalidatePath("/taken");
    return { success: true };
  } catch (error) {
    return { success: false, error: "Task opslaan mislukt" };
  }
}